"use client";

import { Autocomplete as AutocompletePrimitive } from "@base-ui/react/autocomplete";
import type {
  ComponentProps,
  FormEvent,
  KeyboardEvent,
  RefObject,
} from "react";
import {
  useCallback,
  useEffect,
  useLayoutEffect,
  useRef,
  useState,
} from "react";
import {
  COMPOSER_CLIPBOARD_TYPE,
  parseComposerClipboard,
} from "@/lib/composer-clipboard";
import {
  type ActiveQuery,
  type ComposerItemValue,
  type ComposerPart,
  type ComposerQuery,
  type ComposerSelection,
  type ComposerSnapshot,
  type ComposerTokenPart,
  type ComposerTrigger,
  type ComposerValue,
  currentQuery,
  equalValue,
  getComposerText,
  getFilteredItems,
  hasVisibleItems,
  insertItem,
  insertPlainText,
  readSelection,
  readValue,
  restoreSelection,
  writeValue,
} from "@/lib/composer-document";

type ComposerChangeDetails = {
  reason: "input" | "selection" | "history" | "reset";
};
type UseComposerEditorOptions = {
  value: ComposerValue;
  onValueChange: (value: ComposerValue, details: ComposerChangeDetails) => void;
  onSubmit?: (value: ComposerValue) => void;
  onQueryChange?: (query: ComposerQuery | null) => void;
  onAction?: (item: ComposerItemValue, query: ComposerQuery) => void;
  submitOnEmptySuggestions?: boolean;
  triggers?: readonly ComposerTrigger[];
  disabled?: boolean;
  readOnly?: boolean;
  submitDisabled?: boolean;
  allowEmpty?: boolean;
  submitOnEnter?: "desktop" | "always" | "never";
};

type ComposerEditorController = {
  value: ComposerValue;
  inputProps: ComponentProps<"div">;
  formProps: Pick<ComponentProps<"form">, "onSubmit">;
  rootRef: RefObject<HTMLFormElement | null>;
  isEmpty: boolean;
  isTextarea: boolean;
  isComposing: boolean;
  canSubmit: boolean;
  disabled: boolean;
  readOnly: boolean;
  submit: () => void;
  insertTrigger: (character: string) => void;
  reset: (value?: ComposerValue) => void;
  status: "ready" | "loading" | "error";
  tokenHosts: readonly HTMLSpanElement[];
  suggestions: {
    enabled: boolean;
    submitOnEmptySuggestions: boolean;
    items: readonly ComposerItemValue[];
    open: boolean;
    onOpenChange: (open: boolean) => void;
    onItemSelect: (item: ComposerItemValue) => void;
  };
};

export function useComposerEditor({
  value,
  onValueChange,
  onSubmit,
  onQueryChange,
  onAction,
  submitOnEmptySuggestions = false,
  triggers = [],
  disabled = false,
  readOnly = false,
  submitDisabled = false,
  allowEmpty = false,
  submitOnEnter = "always",
}: UseComposerEditorOptions): ComposerEditorController {
  const inputRef = useRef<HTMLDivElement>(null);
  const [inputElement, setInputElement] = useState<HTMLDivElement | null>(null);
  const setInputRef = useCallback((element: HTMLDivElement | null): void => {
    inputRef.current = element;
    setInputElement(element);
  }, []);
  const isTextarea = inputElement?.tagName === "TEXTAREA";
  const history = useRef<{
    current: ComposerSnapshot;
    past: ComposerSnapshot[];
    future: ComposerSnapshot[];
    inputType: string;
    timestamp: number;
  }>({
    current: { value, selection: null },
    past: [],
    future: [],
    inputType: "",
    timestamp: 0,
  });
  const pendingInput = useRef({
    type: "",
    selection: null as ComposerSelection | null,
  });
  const lastSelection = useRef<ComposerSelection | null>(null);
  const historyAction = useRef<(direction: "undo" | "redo") => void>(() => {});
  const rootRef = useRef<HTMLFormElement>(null);
  const composing = useRef(false);
  const [isComposing, setIsComposing] = useState(false);
  const compositionValue = useRef(value);
  const ignoreCompositionInput = useRef(false);
  const dismissedQuery = useRef<string | null>(null);
  const queryAction = useRef<() => void>(() => {});
  const [query, setQuery] = useState<ActiveQuery | null>(null);
  const [tokenHosts, setTokenHosts] = useState<HTMLSpanElement[]>([]);
  const [, forceReconcile] = useState(0);
  const trigger = triggers.find((item) => item.character === query?.character);
  const { contains } = useComposerFilter();
  const options = getFilteredItems(trigger, query, contains);
  const open =
    !isTextarea &&
    !isComposing &&
    !disabled &&
    !readOnly &&
    Boolean(query) &&
    hasVisibleItems(trigger, options);
  const isEmpty = !getComposerText(value);
  const canSubmit =
    !isComposing &&
    !disabled &&
    !readOnly &&
    !submitDisabled &&
    (allowEmpty || Boolean(getComposerText(value).trim()));
  const onQueryChangeRef = useRef(onQueryChange);
  onQueryChangeRef.current = onQueryChange;
  const queryCharacter = query?.character;
  const queryText = query?.text;
  const queryKey = query?.key;

  const syncTokenHosts = useCallback((input: HTMLDivElement): void => {
    const next = Array.from(
      input.querySelectorAll<HTMLSpanElement>(
        '[data-slot="composer-token-renderer"]',
      ),
    );
    setTokenHosts((previous) =>
      previous.length === next.length &&
      previous.every((host, index) => host === next[index])
        ? previous
        : next,
    );
  }, []);

  useEffect(() => {
    onQueryChangeRef.current?.(
      queryCharacter && queryText !== undefined && queryKey
        ? { character: queryCharacter, text: queryText, key: queryKey }
        : null,
    );
  }, [queryCharacter, queryText, queryKey]);

  useEffect(() => {
    if (
      query &&
      (disabled ||
        readOnly ||
        !triggers.some((item) => item.character === query.character))
    )
      setQuery(null);
  }, [disabled, readOnly, query, triggers]);

  useEffect(() => {
    const input = inputElement;
    if (!input || input instanceof HTMLTextAreaElement) return;
    const beforeInput = (event: InputEvent) => {
      if (event.defaultPrevented) return;
      if (disabled || readOnly || event.inputType.startsWith("format")) {
        event.preventDefault();
        return;
      }
      if (
        event.inputType === "historyUndo" ||
        event.inputType === "historyRedo"
      ) {
        event.preventDefault();
        historyAction.current(
          event.inputType === "historyUndo" ? "undo" : "redo",
        );
      } else if (!composing.current) {
        pendingInput.current = {
          type: event.inputType,
          selection: readSelection(input),
        };
      }
    };
    input.addEventListener("beforeinput", beforeInput);
    return () => input.removeEventListener("beforeinput", beforeInput);
  }, [inputElement, disabled, readOnly]);

  useEffect(() => {
    const onSelectionChange = () => {
      const input = inputRef.current;
      if (input && document.activeElement === input && !composing.current) {
        lastSelection.current = readSelection(input);
        queryAction.current();
      }
    };
    document.addEventListener("selectionchange", onSelectionChange);
    return () =>
      document.removeEventListener("selectionchange", onSelectionChange);
  }, []);

  // Check each commit, including edits the controlled owner rejects without changing value.
  useLayoutEffect(() => {
    const input = inputRef.current;
    if (!input || composing.current) return;
    const expected: ComposerValue =
      input instanceof HTMLTextAreaElement
        ? getComposerText(value)
          ? [{ type: "text", text: getComposerText(value) }]
          : []
        : value;
    if (!equalValue(history.current.current.value, expected)) {
      lastSelection.current = null;
      history.current = {
        current: { value: expected, selection: null },
        past: [],
        future: [],
        inputType: "",
        timestamp: 0,
      };
    }
    if (!equalValue(readValue(input), expected)) {
      const selection = readSelection(input);
      writeValue(input, expected);
      restoreSelection(input, selection);
      setQuery(null);
      dismissedQuery.current = null;
    }
    syncTokenHosts(input);
    if (input instanceof HTMLTextAreaElement) {
      input.disabled = disabled;
      input.readOnly = readOnly;
    }
  });

  const updateQuery = (): void => {
    const input = inputRef.current;
    const next =
      input &&
      !composing.current &&
      document.activeElement === input &&
      triggers.length > 0 &&
      !disabled &&
      !readOnly &&
      !(input instanceof HTMLTextAreaElement)
        ? currentQuery(input, triggers)
        : null;
    if (!next || next.key !== dismissedQuery.current)
      dismissedQuery.current = null;
    const active = next?.key === dismissedQuery.current ? null : next;
    setQuery((previous) =>
      previous?.key === active?.key && previous?.node === active?.node
        ? previous
        : active,
    );
  };

  queryAction.current = updateQuery;

  const dismissSuggestions = (): void => {
    dismissedQuery.current = query?.key ?? null;
    setQuery(null);
  };

  const publish = (reason: ComposerChangeDetails["reason"] = "input"): void => {
    const input = inputRef.current;
    if (!input || composing.current || disabled || readOnly) return;
    const next = readValue(input);
    if (!(input instanceof HTMLTextAreaElement)) {
      const previous = history.current;
      if (!equalValue(previous.current.value, next)) {
        const before = pendingInput.current;
        const now = Date.now();
        const group =
          reason === "input" &&
          /^(insertText|deleteContentBackward|deleteContentForward)$/.test(
            before.type,
          ) &&
          previous.inputType === before.type &&
          now - previous.timestamp < 1000 &&
          before.selection?.anchor === previous.current.selection?.anchor &&
          before.selection?.focus === previous.current.selection?.focus;
        if (!group)
          previous.past.push({
            ...previous.current,
            selection: before.selection,
          });
        if (previous.past.length > 100) previous.past.shift();
        previous.future = [];
        previous.current = { value: next, selection: readSelection(input) };
        previous.inputType = before.type;
        previous.timestamp = now;
      }
      pendingInput.current = { type: "", selection: null };
    }
    if (!equalValue(next, value)) onValueChange(next, { reason });
    forceReconcile((revision) => revision + 1);
    syncTokenHosts(input);
    dismissedQuery.current = null;
    updateQuery();
  };

  const selectItem = (suggestion: ComposerItemValue): void => {
    const input = inputRef.current;
    if (
      disabled ||
      readOnly ||
      composing.current ||
      suggestion.disabled ||
      !query ||
      !input?.contains(query.node)
    )
      return;
    pendingInput.current = {
      type: "selection",
      selection: readSelection(input),
    };
    if (suggestion.type === "action" && onAction) {
      const range = document.createRange();
      range.setStart(query.node, query.start);
      range.setEnd(query.node, query.end);
      range.deleteContents();
      range.collapse(true);
      const selection = window.getSelection();
      selection?.removeAllRanges();
      selection?.addRange(range);
      publish("selection");
      setQuery(null);
      onAction(suggestion, query);
      return;
    }
    insertItem(input, query, suggestion);
    publish("selection");
    setQuery(null);
  };

  const insertTrigger = (character: string): void => {
    const input = inputRef.current;
    if (
      !input ||
      input instanceof HTMLTextAreaElement ||
      disabled ||
      readOnly ||
      composing.current ||
      !triggers.some((trigger) => trigger.character === character)
    )
      return;
    const text = getComposerText(readValue(input));
    const selection = readSelection(input) ??
      lastSelection.current ?? {
        anchor: text.length,
        focus: text.length,
      };
    input.focus({ preventScroll: true });
    restoreSelection(input, selection);
    const start = Math.min(selection.anchor, selection.focus);
    const end = Math.max(selection.anchor, selection.focus);
    const preceding = text.slice(0, start);
    const following = text.slice(end);
    const prefix = preceding && !/\s$/u.test(preceding) ? " " : "";
    const suffix = following && !/^\s/u.test(following) ? " " : "";
    pendingInput.current = { type: "trigger", selection: readSelection(input) };
    insertPlainText(input, `${prefix}${character}${suffix}`);
    if (suffix) {
      const caret = start + prefix.length + character.length;
      restoreSelection(input, { anchor: caret, focus: caret });
    }
    publish();
    lastSelection.current = readSelection(input);
  };

  historyAction.current = (direction) => {
    const input = inputRef.current;
    if (
      !input ||
      input instanceof HTMLTextAreaElement ||
      disabled ||
      readOnly ||
      composing.current
    )
      return;
    const state = history.current;
    const source = direction === "undo" ? state.past : state.future;
    const destination = direction === "undo" ? state.future : state.past;
    const snapshot = source.pop();
    if (!snapshot) return;
    destination.push({
      value: readValue(input),
      selection: readSelection(input),
    });
    state.current = snapshot;
    state.inputType = "";
    writeValue(input, snapshot.value);
    restoreSelection(input, snapshot.selection);
    onValueChange(snapshot.value, { reason: "history" });
    forceReconcile((revision) => revision + 1);
    syncTokenHosts(input);
    dismissSuggestions();
  };

  const performSubmit = (): void => {
    if (!canSubmit || composing.current) return;
    dismissSuggestions();
    onSubmit?.(value);
  };

  const submit = (): void => {
    if (!canSubmit || composing.current) return;
    const root = rootRef.current;
    if (root instanceof HTMLFormElement) root.requestSubmit();
    else performSubmit();
  };

  const onKeyDown = (event: KeyboardEvent<HTMLDivElement>): void => {
    if (
      event.defaultPrevented ||
      composing.current ||
      event.nativeEvent.isComposing ||
      event.nativeEvent.keyCode === 229
    )
      return;
    if (
      !(event.currentTarget instanceof HTMLTextAreaElement) &&
      (event.metaKey || event.ctrlKey) &&
      !event.altKey &&
      (event.key.toLowerCase() === "z" ||
        (event.ctrlKey && event.key.toLowerCase() === "y"))
    ) {
      event.preventDefault();
      historyAction.current(
        event.shiftKey || event.key.toLowerCase() === "y" ? "redo" : "undo",
      );
      return;
    }
    if (
      event.key === "Enter" &&
      !event.shiftKey &&
      (submitOnEnter === "always" ||
        (submitOnEnter === "desktop" &&
          window.matchMedia("(pointer: fine)").matches))
    ) {
      event.preventDefault();
      submit();
    }
  };

  return {
    value,
    isEmpty,
    isTextarea,
    isComposing,
    canSubmit,
    disabled,
    readOnly,
    tokenHosts,
    submit,
    insertTrigger,
    rootRef,
    reset: (next = []) => {
      lastSelection.current = null;
      history.current = {
        current: { value: next, selection: null },
        past: [],
        future: [],
        inputType: "",
        timestamp: 0,
      };
      dismissSuggestions();
      onValueChange(next, { reason: "reset" });
      forceReconcile((revision) => revision + 1);
    },
    formProps: {
      onSubmit: (event: FormEvent<HTMLFormElement>) => {
        if (event.defaultPrevented || event.target !== event.currentTarget)
          return;
        event.preventDefault();
        performSubmit();
      },
    },
    inputProps: {
      ref: setInputRef,
      contentEditable: isTextarea ? undefined : !disabled && !readOnly,
      role: "textbox",
      tabIndex: disabled ? -1 : 0,
      suppressContentEditableWarning: true,
      "aria-disabled": disabled || undefined,
      "aria-readonly": readOnly || undefined,
      "aria-multiline": true,
      onKeyDown,
      onKeyUp: (event) => {
        if (!event.defaultPrevented && !composing.current) updateQuery();
      },
      onClick: updateQuery,
      onBlur: (event) => {
        lastSelection.current =
          readSelection(event.currentTarget) ?? lastSelection.current;
        dismissSuggestions();
      },
      onInput: () => {
        if (ignoreCompositionInput.current) return;
        publish();
      },
      onCompositionStart: () => {
        pendingInput.current = {
          type: "composition",
          selection: inputRef.current ? readSelection(inputRef.current) : null,
        };
        composing.current = true;
        setIsComposing(true);
        compositionValue.current = value;
        setQuery(null);
      },
      onCompositionEnd: () => {
        composing.current = false;
        setIsComposing(false);
        ignoreCompositionInput.current = true;
        queueMicrotask(() => {
          ignoreCompositionInput.current = false;
        });
        if (equalValue(compositionValue.current, value)) publish();
        forceReconcile((revision) => revision + 1);
      },
      onCopy: (event) => {
        if (
          event.defaultPrevented ||
          event.currentTarget instanceof HTMLTextAreaElement
        )
          return;
        const selection = window.getSelection();
        if (
          !selection?.rangeCount ||
          selection.isCollapsed ||
          !event.currentTarget.contains(selection.anchorNode) ||
          !event.currentTarget.contains(selection.focusNode)
        )
          return;
        const fragment = document.createElement("div");
        fragment.append(selection.getRangeAt(0).cloneContents());
        const copiedValue = readValue(fragment, false);
        event.clipboardData.setData("text/plain", getComposerText(copiedValue));
        event.clipboardData.setData(
          COMPOSER_CLIPBOARD_TYPE,
          JSON.stringify(copiedValue),
        );
        event.preventDefault();
      },
      onCut: (event) => {
        if (
          event.defaultPrevented ||
          event.currentTarget instanceof HTMLTextAreaElement
        )
          return;
        const selection = window.getSelection();
        if (
          !selection?.rangeCount ||
          selection.isCollapsed ||
          !event.currentTarget.contains(selection.anchorNode) ||
          !event.currentTarget.contains(selection.focusNode)
        )
          return;
        const fragment = document.createElement("div");
        fragment.append(selection.getRangeAt(0).cloneContents());
        const copiedValue = readValue(fragment, false);
        event.clipboardData.setData("text/plain", getComposerText(copiedValue));
        event.clipboardData.setData(
          COMPOSER_CLIPBOARD_TYPE,
          JSON.stringify(copiedValue),
        );
        event.preventDefault();
        if (disabled || readOnly || composing.current) return;
        pendingInput.current = {
          type: "cut",
          selection: readSelection(event.currentTarget),
        };
        selection.getRangeAt(0).deleteContents();
        publish();
      },
      onPaste: (event) => {
        if (
          event.defaultPrevented ||
          event.currentTarget instanceof HTMLTextAreaElement
        )
          return;
        event.preventDefault();
        if (disabled || readOnly || composing.current) return;
        pendingInput.current = {
          type: "paste",
          selection: readSelection(event.currentTarget),
        };
        const pastedValue = parseComposerClipboard(
          event.clipboardData.getData(COMPOSER_CLIPBOARD_TYPE),
        );
        if (pastedValue) {
          const selection = window.getSelection();
          if (
            !selection?.rangeCount ||
            !event.currentTarget.contains(selection.anchorNode) ||
            !event.currentTarget.contains(selection.focusNode)
          )
            return;
          const range = selection.getRangeAt(0);
          range.deleteContents();
          const fragment = document.createElement("div");
          writeValue(fragment, pastedValue);
          const nodes = Array.from(fragment.childNodes).filter(
            (node) =>
              !(
                node instanceof HTMLElement &&
                node.hasAttribute("data-composer-placeholder")
              ),
          );
          const last = nodes.at(-1);
          for (const node of nodes.reverse()) range.insertNode(node);
          if (last) range.setStartAfter(last);
          range.collapse(true);
          selection.removeAllRanges();
          selection.addRange(range);
        } else
          insertPlainText(
            event.currentTarget,
            event.clipboardData.getData("text/plain"),
          );
        publish();
      },
      onDrop: (event) => {
        if (
          event.defaultPrevented ||
          event.currentTarget instanceof HTMLTextAreaElement
        )
          return;
        event.preventDefault();
        if (disabled || readOnly || composing.current) return;
        const text = event.dataTransfer.getData("text/plain");
        if (!text) return;
        const documentWithCaret = document as Document & {
          caretPositionFromPoint?: (
            x: number,
            y: number,
          ) => { offsetNode: Node; offset: number } | null;
          caretRangeFromPoint?: (x: number, y: number) => Range | null;
        };
        const position = documentWithCaret.caretPositionFromPoint?.(
          event.clientX,
          event.clientY,
        );
        const range = documentWithCaret.caretRangeFromPoint?.(
          event.clientX,
          event.clientY,
        );
        const node = position?.offsetNode ?? range?.startContainer;
        const offset = position?.offset ?? range?.startOffset;
        if (
          !node ||
          offset === undefined ||
          !event.currentTarget.contains(node)
        )
          return;
        const token = (
          node instanceof Element ? node : node.parentElement
        )?.closest("[data-composer-token]");
        if (token) {
          const afterToken = document.createRange();
          afterToken.setStartAfter(token);
          afterToken.collapse(true);
          const selection = window.getSelection();
          selection?.removeAllRanges();
          selection?.addRange(afterToken);
        } else {
          window.getSelection()?.collapse(node, offset);
        }
        event.currentTarget.focus({ preventScroll: true });
        pendingInput.current = {
          type: "drop",
          selection: readSelection(event.currentTarget),
        };
        insertPlainText(event.currentTarget, text);
        publish();
      },
    },
    status: trigger?.status ?? "ready",
    suggestions: {
      submitOnEmptySuggestions,
      enabled:
        triggers.length > 0 &&
        !isTextarea &&
        !isComposing &&
        !disabled &&
        !readOnly,
      items: options,
      open,
      onOpenChange: (nextOpen) => {
        if (!nextOpen) dismissSuggestions();
      },
      onItemSelect: selectItem,
    },
  };
}

export const useComposerFilter: typeof AutocompletePrimitive.useFilter =
  AutocompletePrimitive.useFilter;
export {
  type ComposerChangeDetails,
  type ComposerEditorController,
  type ComposerItemValue,
  type ComposerPart,
  type ComposerQuery,
  type ComposerTokenPart,
  type ComposerTrigger,
  type ComposerValue,
  getComposerText,
  type UseComposerEditorOptions,
};

import type { ComposerPart, ComposerValue } from "./composer-document";

export const COMPOSER_CLIPBOARD_TYPE = "application/x-coss-composer";

export function parseComposerClipboard(raw: string): ComposerValue | null {
  if (!raw || raw.length > 100_000) return null;
  try {
    const value: unknown = JSON.parse(raw);
    if (!Array.isArray(value) || value.length > 1_000) return null;
    const parts: ComposerPart[] = [];
    for (const part of value) {
      if (!part || typeof part !== "object") return null;
      if (part.type === "text" && typeof part.text === "string") {
        parts.push({ type: "text", text: part.text });
        continue;
      }
      if (
        (part.type !== "mention" && part.type !== "action") ||
        typeof part.id !== "string" ||
        typeof part.label !== "string" ||
        typeof part.trigger !== "string"
      )
        return null;
      parts.push({
        type: part.type,
        id: part.id,
        label: part.label,
        trigger: part.trigger,
        ...(typeof part.kind === "string" ? { kind: part.kind } : {}),
        ...(typeof part.data === "string" ? { data: part.data } : {}),
        ...(typeof part.text === "string" ? { text: part.text } : {}),
      });
    }
    return parts;
  } catch {
    return null;
  }
}

import type { ReactNode } from "react";
import { getComposerQuery } from "@/lib/composer-query";

type ComposerPart =
  | { type: "text"; text: string }
  | {
      type: "mention" | "action";
      id: string;
      label: string;
      trigger: string;
      kind?: string;
      data?: string;
      text?: string;
    };

type ComposerValue = readonly ComposerPart[];
type ComposerTokenPart = Exclude<ComposerPart, { type: "text" }>;

type ComposerItemValue = {
  id: string;
  label: string;
  disabled?: boolean;
  description?: string;
  icon?: ReactNode;
  type?: "mention" | "action";
  kind?: string;
  data?: string;
  text?: string;
};

type ComposerTrigger = {
  character: string;
  items: readonly ComposerItemValue[];
  status?: "ready" | "loading" | "error";
  itemsFor?: string;
  queryKey?: string;
  showEmpty?: boolean;
  maxQueryLength?: number;
  filter?: ((item: ComposerItemValue, query: string) => boolean) | null;
};

type ComposerQuery = { character: string; text: string; key: string };

const queryNodeIds = new WeakMap<Text, number>();
let nextQueryNodeId = 0;

type ActiveQuery = ComposerQuery & {
  node: Text;
  start: number;
  end: number;
};

function pushText(parts: ComposerPart[], text: string): void {
  if (!text) return;
  const previous = parts[parts.length - 1];
  if (previous?.type === "text") previous.text += text;
  else parts.push({ type: "text", text });
}

function readValue(
  root: HTMLElement,
  ignoreTrailingPlaceholder = true,
): ComposerValue {
  if (root instanceof HTMLTextAreaElement) {
    return root.value ? [{ type: "text", text: root.value }] : [];
  }
  const parts: ComposerPart[] = [];
  function children(parent: HTMLElement): void {
    const nodes = Array.from(parent.childNodes);
    for (const [index, node] of nodes.entries()) {
      if (node instanceof Text) {
        pushText(parts, node.data);
        continue;
      }
      if (!(node instanceof HTMLElement)) continue;
      const tokenType = node.dataset.composerToken;
      if (tokenType === "mention" || tokenType === "action") {
        parts.push({
          type: tokenType,
          id: node.dataset.id ?? "",
          label: node.dataset.label ?? "",
          trigger: node.dataset.trigger ?? "@",
          ...(node.dataset.kind ? { kind: node.dataset.kind } : {}),
          ...(node.dataset.data !== undefined
            ? { data: node.dataset.data }
            : {}),
          ...(node.dataset.text !== undefined
            ? { text: node.dataset.text }
            : {}),
        });
      } else if (node.tagName === "BR") {
        if (node.hasAttribute("data-composer-placeholder")) continue;
        // Browsers end empty lines with a placeholder BR, which is not another newline.
        if (!ignoreTrailingPlaceholder || index !== nodes.length - 1)
          pushText(parts, "\n");
      } else {
        const isBlock = node.tagName === "DIV" || node.tagName === "P";
        if (
          isBlock &&
          index > 0 &&
          !(nodes[index - 1] instanceof HTMLBRElement)
        )
          pushText(parts, "\n");
        children(node);
        if (isBlock && index < nodes.length - 1) {
          const next = nodes[index + 1];
          if (
            !(
              next instanceof HTMLElement &&
              (next.tagName === "DIV" || next.tagName === "P")
            )
          )
            pushText(parts, "\n");
        }
      }
    }
  }
  children(root);
  return parts;
}

function normalizeValue(value: ComposerValue): ComposerValue {
  const parts: ComposerPart[] = [];
  for (const part of value) {
    if (part.type === "text") pushText(parts, part.text);
    else parts.push(part);
  }
  return parts;
}

function equalValue(left: ComposerValue, right: ComposerValue): boolean {
  const a = normalizeValue(left);
  const b = normalizeValue(right);
  return (
    a.length === b.length &&
    a.every((part, index) => {
      const other = b[index];
      if (part.type === "text")
        return other?.type === "text" && part.text === other.text;
      return (
        other?.type !== "text" &&
        other?.type === part.type &&
        other.id === part.id &&
        other.label === part.label &&
        other.trigger === part.trigger &&
        other.kind === part.kind &&
        other.data === part.data &&
        other.text === part.text
      );
    })
  );
}

function getComposerText(value: ComposerValue): string {
  return value
    .map((part) =>
      part.type === "text"
        ? part.text
        : (part.text ?? `${part.trigger}${part.label}`),
    )
    .join("");
}

function createToken(part: ComposerTokenPart): HTMLSpanElement {
  const token = document.createElement("span");
  token.dataset.composerToken = part.type;
  token.dataset.id = part.id;
  token.dataset.label = part.label;
  token.dataset.trigger = part.trigger;
  if (part.kind) token.dataset.kind = part.kind;
  if (part.data !== undefined) token.dataset.data = part.data;
  if (part.text !== undefined) token.dataset.text = part.text;
  token.contentEditable = "false";
  const fallback = document.createElement("span");
  fallback.dataset.slot = "composer-token-fallback";
  fallback.textContent = part.text ?? `${part.trigger}${part.label}`;
  const renderer = document.createElement("span");
  renderer.dataset.slot = "composer-token-renderer";
  token.append(fallback, renderer);
  return token;
}

function writeValue(root: HTMLElement, value: ComposerValue): void {
  if (root instanceof HTMLTextAreaElement) {
    root.value = getComposerText(value);
    return;
  }
  const fragment = document.createDocumentFragment();
  for (const part of value) {
    if (part.type !== "text") fragment.append(createToken(part));
    else if (part.text) fragment.append(document.createTextNode(part.text));
  }
  if (getComposerText(value).endsWith("\n")) {
    const placeholder = document.createElement("br");
    placeholder.dataset.composerPlaceholder = "";
    fragment.append(placeholder);
  }
  root.replaceChildren(fragment);
}

function insertPlainText(root: HTMLElement, text: string): void {
  const selection = window.getSelection();
  if (
    !selection?.rangeCount ||
    !root.contains(selection.anchorNode) ||
    !root.contains(selection.focusNode)
  )
    return;
  const range = selection.getRangeAt(0);
  range.deleteContents();
  const node = document.createTextNode(text.replace(/\r\n?/g, "\n"));
  range.insertNode(node);
  range.setStart(node, node.length);
  range.collapse(true);
  selection.removeAllRanges();
  selection.addRange(range);
}

function placeCaretAfterToken(
  root: HTMLElement,
  selection: Selection | null,
): void {
  if (!selection?.rangeCount) return;
  const range = selection.getRangeAt(0);
  if (!range.collapsed) return;
  const anchor = selection.anchorNode;
  const token = (
    anchor instanceof Element ? anchor : anchor?.parentElement
  )?.closest("[data-composer-token]");
  if (token && root.contains(token)) {
    const next = token.nextSibling;
    if (next instanceof Text && /^\s/u.test(next.data)) {
      selection.collapse(next, 1);
    } else if (token.parentNode) {
      selection.collapse(
        token.parentNode,
        Array.from(token.parentNode.childNodes).indexOf(token) + 1,
      );
    }
    return;
  }
  const { startContainer, startOffset } = range;
  if (startContainer instanceof Text) {
    if (/^\s/u.test(startContainer.data.slice(startOffset)))
      selection.collapse(startContainer, startOffset + 1);
  } else {
    const next = startContainer.childNodes[startOffset];
    if (next instanceof Text && /^\s/u.test(next.data))
      selection.collapse(next, 1);
  }
}

function currentQuery(
  root: HTMLElement,
  triggers: readonly ComposerTrigger[],
): ActiveQuery | null {
  const selection = window.getSelection();
  if (!selection?.isCollapsed || !root.contains(selection.anchorNode))
    return null;
  const node = selection.anchorNode;
  if (
    !(node instanceof Text) ||
    node.parentElement?.closest("[data-composer-token]")
  )
    return null;
  let caret = selection.anchorOffset;
  let merged = false;
  // Paste and token deletion can leave one query split across adjacent text nodes.
  while (node.previousSibling instanceof Text) {
    const previous = node.previousSibling;
    caret += previous.length;
    node.insertData(0, previous.data);
    previous.remove();
    merged = true;
  }
  while (node.nextSibling instanceof Text) {
    const next = node.nextSibling;
    node.appendData(next.data);
    next.remove();
    merged = true;
  }
  if (merged) selection.collapse(node, caret);
  const query = getComposerQuery(
    node.data,
    caret,
    triggers.map((trigger) => trigger.character),
  );
  if (
    !query ||
    query.text.length >
      (triggers.find((trigger) => trigger.character === query.character)
        ?.maxQueryLength ?? Number.POSITIVE_INFINITY)
  )
    return null;
  if (
    query.start === 0 &&
    node.previousSibling?.textContent &&
    !/\s$/u.test(node.previousSibling.textContent)
  )
    return null;
  if (!queryNodeIds.has(node)) queryNodeIds.set(node, ++nextQueryNodeId);
  return {
    ...query,
    node,
    key: `${queryNodeIds.get(node)}:${query.character}:${query.start}:${caret}:${query.text}`,
  };
}

function getFilteredItems(
  trigger: ComposerTrigger | undefined,
  query: ActiveQuery | null,
  defaultFilter: (text: string, query: string) => boolean,
): readonly ComposerItemValue[] {
  if (
    !trigger ||
    !query ||
    (trigger.status && trigger.status !== "ready") ||
    (trigger.itemsFor !== undefined && trigger.itemsFor !== query.text) ||
    (trigger.queryKey !== undefined && trigger.queryKey !== query.key)
  )
    return [];
  if (trigger.filter === null) return trigger.items;
  return trigger.items.filter((item) =>
    trigger.filter
      ? trigger.filter(item, query.text)
      : defaultFilter(item.label, query.text),
  );
}

function hasVisibleItems(
  trigger: ComposerTrigger | undefined,
  options: readonly ComposerItemValue[],
): boolean {
  return Boolean(
    trigger &&
      (options.length ||
        trigger.showEmpty ||
        trigger.status === "loading" ||
        trigger.status === "error"),
  );
}

function insertItem(
  input: HTMLDivElement,
  query: ActiveQuery,
  suggestion: ComposerItemValue,
): void {
  const range = document.createRange();
  range.setStart(query.node, query.start);
  range.setEnd(query.node, query.end);
  const selection = window.getSelection();
  selection?.removeAllRanges();
  selection?.addRange(range);
  input.focus({ preventScroll: true });
  const token = createToken({
    type: suggestion.type ?? "mention",
    id: suggestion.id,
    label: suggestion.label,
    trigger: query.character,
    ...(suggestion.kind ? { kind: suggestion.kind } : {}),
    ...(suggestion.data !== undefined ? { data: suggestion.data } : {}),
    ...(suggestion.text !== undefined ? { text: suggestion.text } : {}),
  });
  const hasSeparator = /^\s/u.test(query.node.data.slice(query.end));
  const trailingSpace = hasSeparator ? "" : " ";
  range.deleteContents();
  const space = trailingSpace ? document.createTextNode(trailingSpace) : null;
  if (space) range.insertNode(space);
  range.insertNode(token);
  if (space) range.setStart(space, 1);
  else range.setStartAfter(token);
  range.collapse(true);
  selection?.removeAllRanges();
  selection?.addRange(range);
  placeCaretAfterToken(input, selection);
  input.focus({ preventScroll: true });
}

type ComposerSelection = { anchor: number; focus: number };

// Use canonical text offsets so chip labels and their icons do not move the caret.
function readSelection(input: HTMLElement): ComposerSelection | null {
  if (input instanceof HTMLTextAreaElement) {
    return document.activeElement === input
      ? {
          anchor:
            input.selectionDirection === "backward"
              ? input.selectionEnd
              : input.selectionStart,
          focus:
            input.selectionDirection === "backward"
              ? input.selectionStart
              : input.selectionEnd,
        }
      : null;
  }
  const selection = window.getSelection();
  if (
    !selection?.anchorNode ||
    !selection.focusNode ||
    !input.contains(selection.anchorNode) ||
    !input.contains(selection.focusNode)
  )
    return null;
  function offset(node: Node, position: number): number {
    const range = document.createRange();
    range.selectNodeContents(input);
    range.setEnd(node, position);
    const fragment = document.createElement("div");
    fragment.append(range.cloneContents());
    return getComposerText(readValue(fragment, false)).length;
  }
  return {
    anchor: offset(selection.anchorNode, selection.anchorOffset),
    focus: offset(selection.focusNode, selection.focusOffset),
  };
}

function restoreSelection(
  input: HTMLElement,
  selection: ComposerSelection | null,
): void {
  if (!selection) return;
  if (input instanceof HTMLTextAreaElement) {
    input.setSelectionRange(
      Math.min(selection.anchor, selection.focus),
      Math.max(selection.anchor, selection.focus),
      selection.anchor > selection.focus ? "backward" : "forward",
    );
    return;
  }
  function point(offset: number): [Node, number] {
    let remaining = offset;
    for (const [index, node] of Array.from(input.childNodes).entries()) {
      const length =
        node instanceof HTMLElement && node.dataset.composerToken
          ? (
              node.dataset.text ??
              `${node.dataset.trigger ?? ""}${node.dataset.label ?? ""}`
            ).length
          : (node.textContent ?? "").length;
      if (remaining <= length) {
        if (node instanceof Text) return [node, remaining];
        return [input, index + (remaining > 0 ? 1 : 0)];
      }
      remaining -= length;
    }
    return [input, input.childNodes.length];
  }
  const [anchor, anchorOffset] = point(selection.anchor);
  const [focus, focusOffset] = point(selection.focus);
  window
    .getSelection()
    ?.setBaseAndExtent(anchor, anchorOffset, focus, focusOffset);
}

type ComposerSnapshot = {
  value: ComposerValue;
  selection: ComposerSelection | null;
};

export {
  type ActiveQuery,
  type ComposerItemValue,
  type ComposerPart,
  type ComposerQuery,
  type ComposerSelection,
  type ComposerSnapshot,
  type ComposerTokenPart,
  type ComposerTrigger,
  type ComposerValue,
  currentQuery,
  equalValue,
  getComposerText,
  getFilteredItems,
  hasVisibleItems,
  insertItem,
  insertPlainText,
  readSelection,
  readValue,
  restoreSelection,
  writeValue,
};

export function getComposerQuery(
  text: string,
  caret: number,
  triggers: readonly string[],
): { character: string; text: string; start: number; end: number } | null {
  let start = -1;
  let character = "";
  for (const trigger of triggers) {
    if (!trigger || trigger.length > caret) continue;
    const index = text.lastIndexOf(trigger, caret - trigger.length);
    if (index > start) {
      start = index;
      character = trigger;
    }
  }
  if (start < 0 || (start > 0 && !/\s/u.test(text.charAt(start - 1))))
    return null;

  const beforeCaret = text.slice(start + character.length, caret);
  if (/^\s/u.test(beforeCaret)) return null;
  if (!/^[\p{L}\p{M}\p{N}\p{Zs}_.’'-]*$/u.test(beforeCaret)) return null;

  // Complete the word at the caret without consuming subsequent prose.
  const suffix = /^[\p{L}\p{M}\p{N}_.’'-]*/u.exec(text.slice(caret))?.[0] ?? "";
  return {
    character,
    text: (beforeCaret + suffix).replace(/\p{Zs}+/gu, " ").trim(),
    start,
    end: caret + suffix.length,
  };
}

import { Loader2Icon } from "lucide-react";
import type React from "react";
import { cn } from "@/lib/utils";

export function Spinner({
  className,
  ...props
}: React.ComponentProps<typeof Loader2Icon>): React.ReactElement {
  return (
    <Loader2Icon
      aria-label="Loading"
      className={cn("animate-spin", className)}
      role="status"
      {...props}
    />
  );
}
